def is_2_5_smooth(num):
    """Checks if a number is of the form 2^c * 5^d."""
    if num <= 0:
        return False
    while num % 2 == 0:
        num //= 2
    while num % 5 == 0:
        num //= 5
    return num == 1

solutions = []
# m = n+1. Since n >= 0, m >= 1. We test m up to 101 (which corresponds to n=100).
for m in range(1, 102):
    m_squared_plus_1 = m*m + 1
    if is_2_5_smooth(m_squared_plus_1):
        solutions.append(m)

print(f"Solutions m up to 101: {solutions}")

def is_power_of_2_or_5(k):
    """Checks if k is of the form 2^c * 5^d."""
    if k <= 0:
        return False

    temp_k = k
    while temp_k > 1:
        if temp_k % 2 != 0 and temp_k % 5 != 0:
            return False
        if temp_k % 2 == 0:
            temp_k //= 2
        elif temp_k % 5 == 0:
            temp_k //= 5
        else:
            # Should not happen if the above checks are correct, but as a safeguard
            return False
    return True

candidates = []
for a in range(6):  # a <= 5
    for b in range(4):  # b <= 3
        power = (2**a) * (5**b)
        n = power - 2

        if n >= 0:
            candidates.append(n)

results = []
print(f"Generated {len(candidates)} candidates.")
print("---")

for n in candidates:
    K = n**2 + 2*n + 2
    is_form = is_power_of_2_or_5(K)
    results.append((n, K, is_form))

# Output the results clearly
for n, K, is_form in results:
    print(f"n = {n:<5} | K = {K:<8} | K is 2^c 5^d: {is_form}")
